package com.jbrempresa.backend.controller;import com.jbrempresa.backend.dto.administracion.EmpresaRelacionDtos.*;import com.jbrempresa.backend.service.EmpresaRelacionService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/empresas-relaciones")@CrossOrigin(origins="http://localhost:4200")public class EmpresaRelacionController{private final EmpresaRelacionService s;public EmpresaRelacionController(EmpresaRelacionService s){this.s=s;}@GetMapping public List<Salida> listar(){return s.listar();}@GetMapping("/{id}/historico")public List<com.jbrempresa.backend.entity.EmpresaRelacionMovimiento> historico(@PathVariable Long id){return s.historico(id);}@GetMapping("/empresas")public List<Opcion> empresas(){return s.empresas();}@GetMapping("/proveedores")public List<Opcion> proveedores(){return s.proveedores();}@PostMapping public Salida crear(@Valid@RequestBody Entrada in){return s.crear(in);}@PutMapping("/{id}")public Salida actualizar(@PathVariable Long id,@Valid@RequestBody Entrada in){return s.actualizar(id,in);}@DeleteMapping("/{id}")public void eliminar(@PathVariable Long id){s.eliminar(id);}@PatchMapping("/{id}/baja")public void baja(@PathVariable Long id,@Valid @RequestBody MovimientoEntrada in){s.estado(id,false,in.causa());}@PatchMapping("/{id}/reactivacion")public void reactivar(@PathVariable Long id,@Valid @RequestBody MovimientoEntrada in){s.estado(id,true,in.causa());}}
